 if(st.qpEarned>=100)changed=unlockAchievement('Q07')||changed;if(st.qpEarned>=1000)changed=unlockAchievement('Q08')||changed;
 if(st.consecutiveFullQuestSets>=7)changed=unlockAchievement('Q09')||changed;if(st.consecutiveQpDays>=100)changed=unlockAchievement('Q010')||changed;
 [[1000,'PR01'],[10000,'PR02'],[100000,'PR03'],[1000000,'PR04'],[10000000,'PR05'],[100000000,'PR06']].forEach(x=>{if(state.rolls>=x[0])changed=unlockAchievement(x[1])||changed});
 if(st.coinsEarned>=100000)changed=unlockAchievement('PR07')||changed;if((state.bankTier||0)>=5)changed=unlockAchievement('PR08')||changed;
 if((state.bankTier||0)>=12)changed=unlockAchievement('PR09')||changed;if((state.activePotions||[]).length&&((state.gearsEquipped||[]).length)&&((state.bankTier||0)>=5))changed=unlockAchievement('PR10')||changed;
 if(tutorialState().phase>=3)changed=unlockAchievement('PR11')||changed;
 if(st.d01)changed=unlockAchievement('D01')||changed;if(st.d02)changed=unlockAchievement('D02')||changed;if(st.d03)changed=unlockAchievement('D03')||changed;
