function hourKey(){return Math.floor(Date.now()/3600000)}
function seededRandom(seed){let x=Math.sin(seed)*10000;return x-Math.floor(x)}
function activeQuestBoard(){return typeof window.questBoard==='function'&&window.questBoard!==questBoard?window.questBoard():questBoard()}
function questBoard(){
 const h=hourKey(); const pool=QUEST_POOL.map((q,i)=>({id:i+1,type:q[0],difficulty:q[1],objective:q[2],target:q[3],_i:i}));
 let seed=h*97+17, selected=[];
 while(selected.length<15){seed=seededRandom(seed)*1000000;const i=Math.floor(seed)%pool.length;const q=pool[i];if(!selected.some(x=>x.id===q.id)){const range=QP_RANGES[q.difficulty];const qp=range[0]+(Math.floor(seededRandom(seed+q.id)*1000)%(range[1]-range[0]+1));selected.push({...q,qp})}}
 return selected;
}
function questState(){const h=hourKey();if(!state.questState||state.questState.hour!==h){const previous=state.questState;state.questState={hour:h,completed:[],progress:{},qp:0,milestones:{}};if(previous&&previous.qp){state.dailyQuota=Math.max(1,(Number(previous.qp)*0.01)+1);achievementState().stats.qpDays=(achievementState().stats.qpDays||0)+1;}}return state.questState}
function questProgress(q){const qs=questState();return qs.progress[q.id]||0}
function completeQuest(id){const qs=questState(),q=activeQuestBoard().find(x=>x.id===id);if(!q||qs.completed.includes(id))return;const progress=qs.progress[id]||0;const target=q.target||1;if(progress<target){if(q.type==='Mixed'){toast('This quest is not complete yet.');return}toast('Progress: '+progress+' / '+target);return}qs.completed.push(id);markTutorialQuest();qs.qp+=q.qp;try{if(q.serverId&&typeof window.eq4RecordQuestProgress==='function')void window.eq4RecordQuestProgress(q,qs.progress[id]||0,true)}catch(err){console.warn('Shared quest progress sync failed:',err)}const ast=achievementState().stats;ast.questsCompleted=(ast.questsCompleted||0)+1;ast.qpEarned=(ast.qpEarned||0)+q.qp;if(qs.completed.length===15){ast.fullQuestSets=(ast.fullQuestSets||0)+1;ast.consecutiveFullQuestSets=(ast.consecutiveFullQuestSets||0)+1;}if(q.coins)ast.coinsEarned=(ast.coinsEarned||0)+q.coins;const n=qs.completed.length;[5,10,15].forEach(m=>{if(n>=m&&!qs.milestones[m]){qs.milestones[m]=true;const r=QUEST_MILESTONES[m];addItem("Potion Gift Box",r.potions);addItem("Coins",r.coins);toast("Quest milestone "+m+" complete: +"+r.potions+" Potion Gift Box, +"+r.coins+" Coins")}});save();render()}
function questView(){
 const qs=questState();let rows=activeQuestBoard();const sort=state.questSort||"difficulty";rows.sort(sort==="type"?(a,b)=>a.type.localeCompare(b.type)||a.difficulty-b.difficulty:(a,b)=>a.difficulty-b.difficulty||a.type.localeCompare(b.type));
 return '<div class="npc-system"><div class="system-head"><button onclick="npcTab(\'home\')">← NPCs</button><div><div class="section-title">Lime · Global Quest Board</div><h1>15 Quests This Hour</h1><p class="muted">Shared hourly set • '+qs.completed.length+'/15 completed • '+qs.qp+' QP</p></div><button onclick="state.questSort=state.questSort===\'difficulty\'?\'type\':\'difficulty\';save();render()">Sort: '+(sort==="difficulty"?"Difficulty":"Type")+'</button></div><div class="quest-grid">'+rows.map(q=>'<div class="quest-card '+(qs.completed.includes(q.id)?'done':'')+'"><div><b>'+q.objective+'</b><small>'+q.type+' · Difficulty '+q.difficulty+' · '+q.qp+' QP</small></div><button '+(qs.completed.includes(q.id)?'disabled':'')+' onclick="completeQuest('+q.id+')">'+(qs.completed.includes(q.id)?'Completed':'Complete')+'</button></div>').join('')+'</div><div class="quest-milestones"><b>Hourly Milestones</b><span>5 → 1 Potion Gift Box + 500 Coins</span><span>10 → 2 Potion Gift Boxes + 1,000 Coins</span><span>15 → 3 Potion Gift Boxes + 1,500 Coins</span></div></div>';
}
function activeShopStock(){return typeof window.shopStock==='function'&&window.shopStock!==shopStock?window.shopStock():shopStock()}
function shopStock(){
 const h=hourKey(); if(!state.shopState||state.shopState.hour!==h){
   const rng=(n)=>seededRandom(h*31+n); const pick=(type,offset)=>{const pool=SHOP_POOL.filter(x=>x[0]===type);let total=pool.reduce((s,x)=>s+x[2],0),r=rng(offset)*total;for(const x of pool){r-=x[2];if(r<=0)return x}return pool[pool.length-1]};
   const used=new Set();const out=[];[["Potion",1],["Potion",2],["Gear",3],["Gear",4],["Item",5],["Item",6]].forEach(([t,o])=>{let x,guard=0;do{x=pick(t,o+guard++);}while(used.has(x[1])&&guard<50);used.add(x[1]);out.push({type:x[0],name:x[1],stock:x[3]+Math.floor(rng(o+20)*(x[4]-x[3]+1)),initialStock:0,bought:false,weight:x[2]})});out.forEach(x=>x.initialStock=x.stock);state.shopState={hour:h,items:out};save()}return state.shopState}
function shopPrice(name){const row=SHOP_POOL.find(x=>x[1]===name);if(!row)return 0;return Math.max(1,Math.floor((auraDef(name)?.rarity?2*auraDef(name).rarity:100)* (1-(bankShopReduction()/100))))}
function bankShopReduction(){const b=state.bankTier||0;return b>=10?10:b>=7?6:b>=4?3:0}
function buyShopItem(i){const shop=activeShopStock(),x=shop.items[i];if(!x||x.stock<=0||x.bought)return;const price=shopPrice(x.name);if((state.inventory.Coins||0)<price){toast("Need "+fmt(price)+" Coins.");return}takeItem("Coins",price);x.stock--;x.bought=true;addItem(x.name,1);save();render();toast("Bought "+x.name)}
function shopView(){const shop=activeShopStock();return '<div class="npc-system"><div class="system-head"><button onclick="npcTab(\'home\')">← NPCs</button><div><div class="section-title">Mari · Shared Hourly Shop</div><h1>Shop</h1><p class="muted">Six global items • 2 Potions • 2 Gears • 2 Ground Items • refreshes hourly</p></div></div><div class="shop-grid">'+shop.items.map((x,i)=>'<div class="shop-card"><small>'+x.type+'</small><h2>'+x.name+'</h2><div>Stock: '+(x.stock>0?x.stock:'Sold Out')+'</div><div>Price: '+fmt(shopPrice(x.name))+' Coins</div><button '+(x.stock<=0||x.bought?'disabled':'')+' onclick="buyShopItem('+i+')">'+(x.bought?'Purchased':x.stock<=0?'Sold Out':'Buy')+'</button></div>').join('')+'</div></div>'}
function bankTierData(){return BANK_TIERS[(state.bankTier||1)-1]||BANK_TIERS[0]}
function bankUpgrade(){const current=state.bankTier||0;if(current>=12){toast("Bank XII already mastered.");return}const next=BANK_TIERS[current];if(!next)return;for(const [item,n] of Object.entries(next[6]))if((item==="Coins"?(state.inventory.Coins||0):(state.inventory[item]||0))<n){toast("Need "+n+" × "+item+".");return}for(const [item,n] of Object.entries(next[6])){if(item==="Coins")takeItem("Coins",n);else if(item==="Gear A"||item==="Gear B")takeItem(item,n);else {for(let i=0;i<n;i++){const a=state.auras.find(x=>x.name===item&&!x.favorite&&!x.equipped);if(!a){toast("Missing "+item+".");return}state.auras=state.auras.filter(x=>x.id!==a.id)}}}state.bankTier=next[0];achievementCheck();save();render();toast("Bank upgraded to "+next[0])}
function bankDeposit(amount){amount=Math.floor(Number(amount));const b=bankTierData();const qs=questState();const used=state.bankDepositHour===hourKey()?state.bankDeposited||0:0;if(!amount||amount<1){toast("Enter a valid amount.");return}if(amount+used>b[3]){toast("Hourly deposit limit reached.");return}if((state.inventory.Coins||0)<amount){toast("Not enough Coins.");return}if((state.bankBalance||0)+amount>b[2]){toast("Bank capacity would be exceeded.");return}takeItem("Coins",amount);state.bankBalance=(state.bankBalance||0)+amount;state.bankDepositHour=hourKey();state.bankDeposited=used+amount;save();render();toast("Deposited "+fmt(amount)+" Coins.")}
function bankWithdraw(){const b=bankTierData();if((state.bankBalance||0)<=0)return;if((state.bankBalance||0)<b[2]&&b[0]<12){toast("Withdrawal unlocks at Bank capacity.");return}addItem("Coins",Math.floor(state.bankBalance||0));state.bankBalance=0;save();render();toast("Bank withdrawn.")}
function bankView(){const b=bankTierData();return '<div class="npc-system"><div class="system-head"><button onclick="npcTab(\'home\')">← NPCs</button><div><div class="section-title">Mari · Personal Bank</div><h1>Bank '+b[0]+'</h1><p class="muted">'+b[4]+' • '+b[1].toFixed(2)+'× hourly interest</p></div><button onclick="bankUpgrade()">Upgrade</button></div><div class="bank-grid"><div class="bank-stat"><span>Stored</span><b>'+fmt(Math.floor(state.bankBalance||0))+' / '+fmt(b[2])+'</b></div><div class="bank-stat"><span>Deposit / hour</span><b>'+fmt(state.bankDeposited||0)+' / '+fmt(b[3])+'</b></div><div class="bank-stat"><span>Multiplier</span><b>'+b[1].toFixed(2)+'×</b></div></div><div class="bank-actions"><input id="depositAmount" type="number" min="1" placeholder="Coins to deposit"><button onclick="bankDeposit(document.getElementById(\'depositAmount\').value)">Deposit</button><button onclick="bankWithdraw()">Withdraw</button></div></div>'}
function craftRecipe(name){const rec=WORKSHOP_RECIPES[name];if(!rec)return;if(settingEnabled('confirmCrafting')&&!confirm('Craft '+name+'? The listed ingredients will be permanently consumed.'))return;const ast=achievementState().stats;for(const [item,n] of Object.entries(rec.recipe)){const aura=state.auras.filter(x=>x.name===item&&!x.favorite&&!x.equipped);const inv=state.inventory[item]||0;if(aura.length+inv<n){toast("Missing "+item+" × "+n);return}}for(const [item,n] of Object.entries(rec.recipe)){let left=n;state.auras=state.auras.filter(x=>{if(left<=0)return true;if(x.name===item&&!x.favorite&&!x.equipped){left--;return false}return true});if(left)takeItem(item,left)}if(rec.type==="Aura"){const d=auraDef(name);state.auras.push({id:'aura-'+Date.now()+'-'+Math.random().toString(36).slice(2,9),name,rarity:d?d.rarity:0,tier:d?d.computedTier:rec.buff,rolledAt:Date.now(),favorite:false,autoSkip:false,autoEquip:false,equipped:false})}else addItem(name,1);if(rec.type==='Gear'){ast.gearCrafted=(ast.gearCrafted||0)+1;ast.gearNames=ast.gearNames||[];if(!ast.gearNames.includes(name))ast.gearNames.push(name);const adv=(rec.buff||'').match(/Advance (X{0,3}(?:IX|IV|V|VI{0,3})|XXV?)/);if(adv){const roman=adv[1];const vals={I:1,V:5,X:10};const value=[...roman].reduce((t,c,i)=>t+(vals[c]<(vals[roman[i+1]]||0)?-vals[c]:vals[c]),0);if(value>=5)ast.advanceV=true;if(value===10)ast.advanceX=true;if(value>15)ast.advanceGTXV=true;}const adv2=(rec.buff||'').match(/Advance (\w+)/);if(adv2&&['XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX','XXI','XXII','XXIII','XXIV','XXV'].includes(adv2[1]))ast.advanceGTXV=true;}if(rec.type==='Potion'){ast.potionsCrafted=(ast.potionsCrafted||0)+1;ast.potionNames=ast.potionNames||[];if(!ast.potionNames.includes(name))ast.potionNames.push(name);}markTutorialCraft(name);questCraftHook();achievementCheck();save();render();toast("Crafted "+name)}
function craftPotion(name){if(!POTION_RECIPES[name]){toast('No recipe exists for '+name+'.');return}craftRecipe(name)}
function questCraftHook(){const qs=questState();activeQuestBoard().forEach(function(q){if(q.type==='Crafting')qs.progress[q.id]=(qs.progress[q.id]||0)+1});save()}
function recipeAvailable(name){const rec=WORKSHOP_RECIPES[name];if(!rec)return false;return Object.entries(rec.recipe).every(function(e){const item=e[0],n=e[1];return state.auras.filter(function(a){return a.name===item&&!a.favorite&&!a.equipped}).length+(state.inventory[item]||0)>=n})}
function autoAddRecipe(name){const rec=WORKSHOP_RECIPES[name];if(!rec)return;state.craftingSelection=state.craftingSelection||{};state.craftingSelection[name]={};Object.entries(rec.recipe).forEach(function(e){const item=e[0],n=e[1];const aura=state.auras.filter(function(a){return a.name===item&&!a.favorite&&!a.equipped}).slice(0,n).map(function(a){return a.id});const left=n-aura.length;state.craftingSelection[name][item]={auras:aura,items:Math.min(left,state.inventory[item]||0)};});save();toast('Auto Add filled '+name+'.');render()}
function workshopView(){const names=Object.keys(WORKSHOP_RECIPES);return `<div class="npc-system"><div class="system-head"><button onclick="npcTab('home')">← NPCs</button><div><div class="section-title">Jake · Workshop</div><h1>Crafting</h1><p class="muted">Add ingredients manually or use Auto Add. Favorited/equipped Auras are protected.</p></div></div><div class="recipe-grid">${names.map(name=>{const r=WORKSHOP_RECIPES[name];return '<div class="recipe-card"><small>'+r.type+'</small><h2>'+name+'</h2><p>'+r.buff+'</p><div>'+Object.entries(r.recipe).map(([k,v])=>'<span>'+v+' × '+k+'</span>').join('')+'</div><div class="recipe-actions"><button onclick="autoAddRecipe('+attrArg(name)+')">Auto Add</button><button '+(recipeAvailable(name)?'':'disabled')+' onclick="craftRecipe('+attrArg(name)+')">Craft</button></div></div>'}).join('')}</div></div>`}
function cauldronView(){const names=Object.keys(POTION_EFFECTS);return `<div class="npc-system"><div class="system-head"><button onclick="npcTab('home')">← NPCs</button><div><div class="section-title">Stella · Cauldron</div><h1>Potions</h1><p class="muted">Craft, use, and enhance Potions. Curse duration is 10× the active duration.</p></div></div><div class="potion-grid">${names.map(name=>{const craftable=!!POTION_RECIPES[name];return '<div class="potion-card"><small>Potion</small><h2>'+name+'</h2><p>'+POTION_EFFECTS[name]+'</p>'+(craftable?'<button onclick="craftPotion('+attrArg(name)+')">Craft</button>':'')+'<button onclick="usePotion('+attrArg(name)+')">Use</button>'+(BREWING_STAND[name]?'<button onclick="enhancePotion('+attrArg(name)+')">Enhance</button>':'')+'</div>'}).join('')}</div><div class="panel" style="margin-top:18px"><div class="section-title">Brewing Stand</div><p class="muted">Enhancement consumes the base Potion, Dark Points, and Coins before the attempt. Failure consumes all three.</p></div></div>`}function potionDurationMs(name){const p=POTION_EFFECTS[name]||'';const m=p.match(/for (\d+) (seconds?|minutes?|hours?)/i);if(!m)return 300000;const n=Number(m[1]),u=m[2].toLowerCase();return n*(u.startsWith('hour')?3600000:u.startsWith('minute')?60000:1000)}
function potionCurseStrength(name){return /Curse/i.test(POTION_EFFECTS[name]||'')?1:0}
function enhancePotion(name){const cfg=BREWING_STAND[name];if(!cfg||!hasItem(name,1))return;if((state.inventory['Dark Points']||0)<cfg.dark){toast('Need '+cfg.dark+' Dark Points.');return}if((state.inventory.Coins||0)<cfg.coins){toast('Need '+fmt(cfg.coins)+' Coins.');return}takeItem(name,1);takeItem('Dark Points',cfg.dark);takeItem('Coins',cfg.coins);const success=Math.random()<cfg.success;if(success){const enhanced='Enhanced '+name;addItem(enhanced,1);const ast=achievementState().stats;ast.potionEnhancements=(ast.potionEnhancements||0)+1;toast('Brewing Stand succeeded: '+enhanced+' ×'+cfg.multiplier)}else toast('Brewing Stand failed. The Potion, Dark Points, and Coins were consumed.');achievementCheck();save();render()}
function activateCurse(name,brewingMultiplier,copies){const strength=potionCurseStrength(name)*(brewingMultiplier||1)*Math.max(1,copies||1);if(!strength)return;const duration=potionDurationMs(name)*10;state.curses=state.curses||{};state.curses[name]={strength:strength,expires:Date.now()+duration};const ast=achievementState().stats;ast.curseReceived=(ast.curseReceived||0)+1;ast.curseStacks=(ast.curseStacks||0)+Math.max(1,copies||1);toast('Curse active: '+name+' ×'+strength.toFixed(2));save()}



/* Phase 4 — live Supabase global integration.
 * supabase.js owns Auth/client creation; this module connects the existing UI
 * to the already-secured Phase 4 tables without exposing privileged keys.
 */
var EQUINOX_GLOBAL_DATA=window.EQUINOX_GLOBAL_DATA=window.EQUINOX_GLOBAL_DATA||{profiles:[],presence:[],chat:[],loaded:false,lastRefresh:0};
function eq4escape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

async function eq4RefreshGlobal(force){
 if(typeof EQUINOX_SUPABASE==='undefined')return false;
 const gd=window.EQUINOX_GLOBAL_DATA=window.EQUINOX_GLOBAL_DATA||{profiles:[],presence:[],chat:[],loaded:false,lastRefresh:0,loading:false,errors:[]};
 const now=Date.now();
 if(gd.loading)return false;
 if(!force&&gd.loaded&&now-Number(gd.lastRefresh||0)<10000)return true;
 gd.loading=true;gd.errors=[];
 try{
   const [p,o,ch]=await Promise.all([
     EQUINOX_SUPABASE.from('profiles').select('id,username,auras_collected,collective_rarity,roll_count,rarest_roll_rarity,global_rank,equipped_aura_id').order('auras_collected',{ascending:false}).limit(10),
     EQUINOX_SUPABASE.from('online_presence').select('user_id,username,global_rank,equipped_aura_name,equipped_aura_rarity,last_seen').gte('last_seen',new Date(Date.now()-90000).toISOString()).order('last_seen',{ascending:false}).limit(10),
     EQUINOX_SUPABASE.from('chat_messages').select('id,user_id,username,global_rank,equipped_aura_name,equipped_aura_rarity,message,created_at').order('created_at',{ascending:false}).limit(150)
   ]);
   if(p.error){gd.errors.push('Players: '+p.error.message)}else gd.profiles=p.data||[];
   if(o.error){gd.errors.push('Online: '+o.error.message)}else gd.presence=o.data||[];
   if(ch.error){gd.errors.push('Chat: '+ch.error.message)}else gd.chat=(ch.data||[]).reverse();
   gd.loaded=true;gd.lastRefresh=Date.now();
   if(state&&state.activeTab==='Global')render();
   return gd.errors.length===0;
 }catch(err){
   gd.errors.push(String(err?.message||err));gd.loaded=true;gd.lastRefresh=Date.now();
   if(state&&state.activeTab==='Global')render();
   return false;
 }finally{gd.loading=false}
}
function eq4Rows(field){
  return window.EQUINOX_GLOBAL_DATA.profiles.slice().sort((a,b)=>Number(b[field]||0)-Number(a[field]||0)).slice(0,10);
}

function eq4GlobalView(){
 const gd=window.EQUINOX_GLOBAL_DATA=window.EQUINOX_GLOBAL_DATA||{profiles:[],presence:[],chat:[],loaded:false,lastRefresh:0,loading:false,errors:[]};
 const g=globalStats();
 const status=gd.loading?'SYNCING GLOBAL DATA…':gd.errors?.length?'GLOBAL PARTIAL':'GLOBAL LIVE';
 const statusDetail=gd.errors?.length?gd.errors.join(' • '):'Supabase connected';
 const makeBoard=function(title,field,rows){
   const sorted=(rows||[]).slice().sort(function(a,b){return Number(b[field]||0)-Number(a[field]||0)}).slice(0,10);
   return '<section class="global-board panel"><div class="global-board-head"><div class="section-title">'+title+'</div><span>TOP 10</span></div>'+
     (sorted.length?sorted.map(function(x,i){return '<div class="leader-row"><span><b>#'+(i+1)+'</b> '+eq4escape(x.username||'Player')+'</span><strong>'+fmt(Number(x[field]||0))+'</strong></div>'}).join(''):'<div class="empty">No players recorded yet.</div>')+
     '</section>';
 };
 const globalBoards=[['Auras Collected','auras_collected'],['Collective Rarity','collective_rarity'],['Rarest Roll','rarest_roll_rarity'],['Roll Count','roll_count']]
   .map(function(p){return makeBoard(p[0],p[1],gd.profiles)}).join('');
 const onlineBoards=[['Auras Collected','auras_collected'],['Collective Rarity','collective_rarity'],['Rarest Roll','rarest_roll_rarity'],['Roll Count','roll_count']]
   .map(function(p){return makeBoard(p[0],p[1],gd.presence)}).join('');
 const online=gd.presence.map(function(x){
   return '<div class="online-row"><div><b>'+eq4escape(x.username||'Player')+'</b><small>'+eq4escape(x.global_rank||'Unranked')+'</small></div><span class="online-state">ONLINE</span><span>'+eq4escape(x.equipped_aura_name||'None')+(x.equipped_aura_rarity?' • 1/'+fmt(x.equipped_aura_rarity):'')+'</span></div>';
 }).join('')||'<div class="empty">No players currently online.</div>';
 const chat=gd.chat.map(function(m){
   const msg=String(m.message||'');
   const flaggable=/(^|\\s)(you|u|ur|your|youre|you're)\\s+(are|r|is)|@\\w+|kill\\s+(yourself|urself)|go\\s+die|nobody\\s+wants\\s+you|hate\\s+you|shut\\s+up/i.test(msg);
   return '<div class="chat-msg"><div class="chat-author"><b>'+eq4escape(m.username||'Player')+'</b><small>'+eq4escape(m.global_rank||'Unranked')+' • '+eq4escape(m.equipped_aura_name||'None')+(m.equipped_aura_rarity?' • 1/'+fmt(m.equipped_aura_rarity):'')+'</small></div><span>'+eq4escape(msg)+'</span>'+(flaggable?' <button class="chat-flag" onclick="eq4FlagChat('+m.id+')">Flag</button>':'')+'</div>';
 }).join('')||'<div class="empty">No messages yet.</div>';
 return '<div class="global-page">'+
   '<div class="panel global-profile"><div><div class="section-title">GLOBAL PROFILE</div><h1>'+eq4escape(g.username||'Player')+'</h1><p class="muted">Equipped Aura: '+eq4escape(g.equipped||'None')+(g.title?' • Title: ['+eq4escape(g.title)+']':'')+'</p></div><div class="global-metrics"><span>Unique Auras <b>'+fmt(g.aurasCollected||0)+'</b></span><span>Rarest Roll <b>1/'+fmt(g.rarestRoll||0)+'</b></span><span>Rolls <b>'+fmt(g.rollCount||0)+'</b></span></div></div>'+
   '<div class="global-status"><b>'+status+'</b><span>'+eq4escape(statusDetail)+'</span></div>'+
   '<section class="global-group"><div class="global-group-title"><h2>GLOBAL LEADERBOARDS</h2><span>UPDATED HOURLY</span></div><div class="global-boards">'+globalBoards+'</div></section>'+
   '<section class="global-group"><div class="global-group-title"><h2>ONLINE LEADERBOARDS</h2><span>TOP 10 ONLINE</span></div><div class="global-boards">'+onlineBoards+'</div></section>'+
   '<div class="panel online-panel"><div class="section-title">ONLINE PLAYERS</div>'+online+'</div>'+
   '<div class="panel chat-panel"><div class="section-title">GLOBAL CHAT <span class="section-meta">150 messages max · 150 characters</span></div><div class="chat-log">'+chat+'</div><div class="chat-compose"><input id="globalChatInput" maxlength="150" placeholder="Message Global Chat…"><button onclick="eq4SendChat()">Send</button></div></div>'+
   '</div>';
}
async function eq4SendChat(){
  if(typeof EQUINOX_SUPABASE==='undefined')return;
  const input=document.getElementById('globalChatInput');
  const message=(input?.value||'').trim().slice(0,150);
  if(!message)return;
  const {data:sessionData}=await EQUINOX_SUPABASE.auth.getSession();
  const user=sessionData?.session?.user;
  if(!user)return;
  const ban=await EQUINOX_SUPABASE.from('chat_bans').select('banned_until').eq('user_id',user.id).maybeSingle();
  if(ban.data?.banned_until&&new Date(ban.data.banned_until)>new Date()){toast('Global Chat is unavailable while your account is banned.');return;}
  const account=JSON.parse(localStorage.getItem('equinox-user')||'{}');
  const aura=state.auras.find(a=>a.equipped);
  const {error}=await EQUINOX_SUPABASE.from('chat_messages').insert({
    user_id:user.id,
    username:account.username||state.username||'Player',
    global_rank:state.globalRank||'Unranked',
    equipped_aura_id:aura?.id||null,
    equipped_aura_name:aura?.name||null,
    equipped_aura_rarity:aura?.rarity||null,
    message:message
  });
  if(error){toast(error.message);return;}
  input.value='';
  await eq4RefreshGlobal(true);
  render();
}

async function eq4FlagChat(messageId){
  if(typeof EQUINOX_SUPABASE==='undefined')return;
  const {data:sessionData}=await EQUINOX_SUPABASE.auth.getSession();
  const user=sessionData?.session?.user;
  if(!user)return;
  const reason=prompt('Why are you flagging this message?');
  if(!reason)return;
  const {error}=await EQUINOX_SUPABASE.from('chat_flags').insert({message_id:messageId,flagger_id:user.id,reason:reason.slice(0,200)});
  toast(error?'Unable to flag this message.':'Message flagged.');
}

async function eq4Presence(){
  if(typeof EQUINOX_SUPABASE==='undefined')return;
  const {data:sessionData}=await EQUINOX_SUPABASE.auth.getSession();
  const user=sessionData?.session?.user;
  if(!user)return;
  const account=JSON.parse(localStorage.getItem('equinox-user')||'{}');
  const aura=state.auras.find(a=>a.equipped);
  await EQUINOX_SUPABASE.from('online_presence').upsert({
    user_id:user.id,
    username:account.username||state.username||'Player',
    global_rank:state.globalRank||'Unranked',
    equipped_aura_id:aura?.id||null,
    equipped_aura_name:aura?.name||null,
    equipped_aura_rarity:aura?.rarity||null,
    last_seen:new Date().toISOString()
  },{onConflict:'user_id'});
}

function installEquinoxPhase4(){
  if(window.__equinoXPhase4Installed||typeof EQUINOX_SUPABASE==='undefined'){if(typeof EQUINOX_SUPABASE==='undefined')setTimeout(installEquinoxPhase4,100);return;}
  window.__equinoXPhase4Installed=true;
  if(typeof globalView==='function')globalView=eq4GlobalView;
  window.eq4SendChat=eq4SendChat;
  window.eq4FlagChat=eq4FlagChat;
  eq4RefreshGlobal(true);
  eq4Presence();
  setInterval(function(){if(state&&state.activeTab==='Global')eq4RefreshGlobal(false);},10000);
  setInterval(eq4Presence,20000);
  try{
    EQUINOX_SUPABASE.channel('equinox-phase4-live')
      .on('postgres_changes',{event:'*',schema:'public',table:'profiles'},()=>eq4RefreshGlobal(true))
      .on('postgres_changes',{event:'*',schema:'public',table:'chat_messages'},()=>eq4RefreshGlobal(true))
      .on('postgres_changes',{event:'*',schema:'public',table:'online_presence'},()=>eq4RefreshGlobal(true))
      .subscribe();
  }catch(e){console.warn('Realtime unavailable; global polling remains active.',e);}
  render();
}
setTimeout(installEquinoxPhase4,0);


/* ===== Equinox application renderer =====
 * Mounts the existing game systems into #app. Kept in the base app so
 * authentication, Phase 4/5/6, and every game action share one renderer.
 */
function render(){
  const root=document.getElementById('app');
  if(!root)return;
  root.className=(state.settings?.performanceMode!==false?'performance-mode ':'')+(state.settings?.reducedMotion?'reduced-motion':'');
  try{
    const tabs=[['Roll','Roll'],['Inventory','Inventory'],['NPCs','NPCs'],['Global','Global'],['Achievements','Achievements'],['Settings','Settings']];
    const recent=(state.recent||[]).slice(0,8);
    const latest=state.lastRollResult||recent[0];
    const equipped=(state.auras||[]).find(function(a){return a.equipped});
    const worldLuck=typeof totalLuck==='function'?totalLuck():1;
    const worldSpeed=typeof totalSpeed==='function'?totalSpeed():1;
    const computedRollTime=typeof rollTimeSeconds==='function'?rollTimeSeconds():11;
    const rollTime=state.rolling?Math.max(1,Number(state.rollDuration||computedRollTime)):computedRollTime;
    const cooldownRemaining=Math.max(0,(Number(state.rollCooldownUntil||0)-Date.now())/1000);
    const latestText=latest
      ? '<div class="roll-result"><div class="section-title">LATEST ROLL</div><h2>'+eq4escape(latest.name)+'</h2><p>1/'+fmt(latest.rolledRarity||latest.rarity||0)+(latest.breakthrough?' · BREAKTHROUGH':'')+(latest.bonus?' · BONUS ROLL':'')+'</p></div>'
      : '<div class="roll-result"><div class="section-title">LATEST ROLL</div><h2>Nothing yet</h2><p class="muted">Your first Aura is waiting.</p></div>';
    const recentRows=recent.map(function(a){
      return '<div class="recent-row"><b>'+eq4escape(a.name)+'</b><span>1/'+fmt(a.rolledRarity||a.rarity||0)+'</span><small>#'+fmt(a.roll||0)+'</small></div>';
    }).join('');
    const potionRows=(state.activePotions||[]).map(function(p){
      const remaining=p.rolls?String(p.rolls)+' roll'+(p.rolls===1?'':'s'):(p.expires?Math.max(0,(p.expires-Date.now())/1000).toFixed(0)+'s':'Active');
      return '<div class="buff-row"><b>'+eq4escape(p.name)+'</b><span>'+(p.luck?'+'+percentText(p.luck)+' Luck':'')+(p.luck&&p.speed?' · ':'')+(p.speed?'+'+percentText(p.speed)+' Speed':'')+' <em>'+remaining+'</em></span></div>';
    }).join('');
    const pendingPotionRows=(state.pendingRollPotions||[]).map(function(p,i){
      return '<div class="buff-row pending-buff"><b>'+eq4escape(p.name)+'</b><span>'+(p.luck?'+'+percentText(p.luck)+' Luck':'')+(p.luck&&p.speed?' · ':'')+(p.speed?'+'+percentText(p.speed)+' Speed':'')+' <em>NEXT ROLL'+(i?' · QUEUED':'')+'</em></span></div>';
    }).join('');
    const gearRows=(state.gearsEquipped||[]).map(function(name){
      const l=gearLuckForName(name),s=gearSpeedForName(name);
      return '<div class="buff-row"><b>'+eq4escape(name)+'</b><span>'+(l?'+'+percentText(l)+' Luck':'')+(l&&s?' · ':'')+(s?'+'+percentText(s)+' Speed':'')+'</span></div>';
    }).join('');
    const activeBuffs=(gearRows+potionRows+pendingPotionRows)||'<div class="empty">No active effects.</div>';
    let main='';
    if(state.activeTab==='Inventory')main=inventoryView();
    else if(state.activeTab==='NPCs'){
      if(state.npcTab==='quests')main=questView();
      else if(state.npcTab==='shop')main=shopView();
      else if(state.npcTab==='bank')main=bankView();
      else if(state.npcTab==='workshop')main=workshopView();
      else if(state.npcTab==='cauldron')main=cauldronView();
      else main='<div class="panel"><div class="section-title">NPC SYSTEMS</div><h1>Equinox NPCs</h1><p class="muted">Choose a system to interact with the world.</p><div class="npc-grid"><button onclick="npcTab(\'quests\')">Lime · Quests</button><button onclick="npcTab(\'shop\')">Mari · Shop</button><button onclick="npcTab(\'bank\')">Mari · Bank</button><button onclick="npcTab(\'workshop\')">Jake · Workshop</button><button onclick="npcTab(\'cauldron\')">Stella · Cauldron</button></div></div>';
    }else if(state.activeTab==='Global'){
      try{
        const gd=window.EQUINOX_GLOBAL_DATA=window.EQUINOX_GLOBAL_DATA||{profiles:[],presence:[],chat:[],loaded:false,lastRefresh:0,loading:false,errors:[]};
        if(typeof window.eq4RefreshGlobal==='function' && (!gd.loaded || Date.now()-Number(gd.lastRefresh||0)>10000))void window.eq4RefreshGlobal(true);
        main=typeof window.globalView==='function'?window.globalView():eq4GlobalView();
      }catch(e){
        console.warn('Global view fallback:',e);
        main='<div class="panel"><div class="section-title">GLOBAL</div><h1>Global systems are connecting…</h1><p class="muted">Your local game remains available while the shared global services reconnect.</p></div>';
      }
    }else if(state.activeTab==='Achievements'){try{main=achievementsView()}catch(err){console.warn('Achievement view failed:',err);main='<div class="panel"><div class="section-title">ACHIEVEMENTS</div><h1>Achievements</h1><p class="muted">Achievement data is temporarily unavailable. Your progress is still saved.</p></div>';}}
    else if(state.activeTab==='Settings')main=settingsView();
    else{
      const cooldownHint=rollTime.toFixed(2)+'s';
      const cooldownStatus=state.rolling?'ROLLING · '+cooldownRemaining.toFixed(1)+'s':cooldownRemaining>0.01?'NEXT ROLL IN '+cooldownRemaining.toFixed(1)+'s':'READY';
      main='<div class="roll-grid"><div class="panel hero"><div class="section-title">THE ROLL</div><h1>Equinox</h1><p class="muted">'+eq4escape(String(state.biome||'Normal'))+' · '+eq4escape(String(state.dayNight||'Day'))+'</p>'+latestText+'<button class="roll-button" onclick="roll()">ROLL</button><div class="roll-time"><span>ROLL TIME</span><b>'+cooldownHint+'</b><small>'+cooldownStatus+'</small></div><p class="muted">Coins: '+fmt(state.inventory?.Coins||0)+' · Aura Storage: '+fmt(auraSlots())+'/'+fmt(state.auraCapacity||20)+'</p></div><div class="panel"><div class="section-title">RECENT ROLLS</div>'+(recentRows||'<div class="empty">No rolls yet.</div>')+'</div></div>';
    }
    const worldPanel='<aside class="world-panel"><div class="world-kicker">CURRENT WORLD</div><div class="world-name">'+eq4escape(String(state.biome||'Normal'))+'</div><div class="world-dimension">'+eq4escape(String(state.dimension||'Isles of Luck'))+'</div><div class="world-stats"><div class="world-stat"><span>Day / Night</span><b>'+eq4escape(String(state.dayNight||'Day'))+'</b></div><div class="world-stat"><span>Total Luck</span><b>'+Number(worldLuck||1).toFixed(2)+'×</b></div><div class="world-stat"><span>Roll Speed</span><b>'+Number(worldSpeed||1).toFixed(2)+'×</b></div><div class="world-stat"><span>Roll Time</span><b>'+rollTime.toFixed(2)+'s</b></div><div class="world-stat"><span>Equipped Aura</span><b>'+eq4escape(equipped?.name||'None')+'</b></div></div><div class="world-block"><div class="section-title">ACTIVE EFFECTS</div><div class="buff-list">'+activeBuffs+'</div></div></aside>';
    root.innerHTML='<div id="notices" aria-live="polite"></div><div class="topbar"><div class="logo">☯ EQUINOX</div><div class="topstats"><span>Rolls <b>'+fmt(state.rolls||0)+'</b></span><span>Luck <b>'+Number(worldLuck||1).toFixed(2)+'×</b></span><span>Speed <b>'+Number(worldSpeed||1).toFixed(2)+'×</b></span><span>Biome <b>'+eq4escape(String(state.biome||'Normal'))+'</b></span></div></div><div class="layout tab-position-'+(state.settings?.tabPosition||'left')+'"><aside class="tabs">'+tabs.map(function(t){return '<button class="tab '+(state.activeTab===t[0]?'active':'')+'" onclick="tab(\''+t[0]+'\')">'+t[1]+'</button>'}).join('')+'</aside><main>'+main+'</main>'+worldPanel+'</div>'+ (typeof tutorialView==='function'?tutorialView():'');
    const rollButton=root.querySelector('.roll-button');
    if(rollButton){const ready=cooldownRemaining<=0.01;rollButton.disabled=!ready||!!state.rolling;rollButton.textContent=state.rolling?'ROLLING '+cooldownRemaining.toFixed(1)+'s':ready?'ROLL':'WAIT '+cooldownRemaining.toFixed(1)+'s';}
    wireInventory();
  }catch(e){
    console.error('Equinox render failed',e);
    const box=document.getElementById('app');
    if(box)box.innerHTML='<div class="panel\" style="margin:24px\"><div class="section-title">EQUINOX ERROR</div><h1>The game could not render.</h1><p class="muted">'+eq4escape(String(e?.message||e))+'</p><button onclick="location.reload()">Reload Equinox</button></div>';
  }
}
window.render=render;
window.state=state;
window.save=save;
window.roll=roll;
window.usePotion=usePotion;
window.craftPotion=craftPotion;
window.eq4GlobalView=typeof eq4GlobalView==='function'?eq4GlobalView:null;
window.globalView=eq4GlobalView;
window.eq4RefreshGlobal=eq4RefreshGlobal;
window.eq4Presence=eq4Presence;
window.tab=tab;window.npcTab=npcTab;window.achievementTab=achievementTab;window.equipAchievementTitle=equipAchievementTitle;window.completeQuest=completeQuest;window.buyShopItem=buyShopItem;window.craftRecipe=craftRecipe;window.craftPotion=craftPotion;window.enhancePotion=enhancePotion;window.sendChat=sendChat;window.setTabPosition=setTabPosition;window.toggleSetting=toggleSetting;
window.questBoard=questBoard;
window.questState=questState;
window.shopStock=shopStock;
window.equipAura=equipAura;
window.equipGear=equipGear;
window.equinoxReloadLocalState=function(){
  state=normalizeState(load());
  window.state=state;
  bankTick();
  if(typeof render==='function')render();
};
try{window.dispatchEvent(new Event('equinox-render-ready'))}catch(_){}
render();
